window.__votdWeek && window.__votdWeek({"week":"2028-02-07","reading":"2 Nephi 3–5","days":[{"d":"2028-02-07","ref":"2 Nephi 3:4","b":"2 Nephi","c":3,"v":4,"he":"כִּי הִנֵּה אַתָּה פְּרִי חֲלָצַי וַאֲנִי מִזֶּרַע יוֹסֵף אֲשֶׁר הוּבַל שְׁבִי מִצְרָיְמָה וּגְדוֹלוֹת בְּרִיתוֹת יְהוָה אֲשֶׁר כָּרַת לְיוֹסֵף׃","en":"For behold, thou art the fruit of my loins; and I am a descendant of Joseph who was carried captive into Egypt. And great were the covenants of the Lord which he made unto Joseph."},{"d":"2028-02-08","ref":"2 Nephi 3:9","b":"2 Nephi","c":3,"v":9,"he":"וְהָיָה גָדוֹל כְּמֹשֶׁה אֲשֶׁר אָמַרְתִּי אָקִים לָכֶם לְהוֹשִׁיעַ עַמִּי בֵּית־יִשְׂרָאֵל׃","en":"And he shall be great like unto Moses, whom I have said I would raise up unto you, to deliver my people, O house of Israel."},{"d":"2028-02-09","ref":"2 Nephi 3:15","b":"2 Nephi","c":3,"v":15,"he":"וּשְׁמוֹ יִקָּרֵא עַל־שְׁמִי וְהָיָה עַל־שֵׁם אָבִיו וְיִהְיֶה כָּמוֹנִי כִּי הַדָּבָר אֲשֶׁר יוֹצִיא יְהוָה בְּיָדוֹ בִּגְבוּרַת יְהוָה יָבִיא עַמִּי לִישׁוּעָה׃","en":"And his name shall be called after me; and it shall be after the name of his father. And he shall be like unto me; for the thing, which the Lord shall bring forth by his hand, by the power of the Lord shall bring my people unto salvation."},{"d":"2028-02-10","ref":"2 Nephi 4:31","b":"2 Nephi","c":4,"v":31,"he":"יְהוָה הֲתִגְאַל נַפְשִׁי הֲתַצִּילֵנִי מִידֵי אוֹיְבָי הֲתַעֲשֵׂנִי לְמַעַן אֶרְעַד לְמַרְאֵה חֵטְא׃","en":"O Lord, wilt thou redeem my soul? Wilt thou deliver me out of the hands of mine enemies? Wilt thou make me that I may shake at the appearance of sin?"},{"d":"2028-02-11","ref":"2 Nephi 5:8","b":"2 Nephi","c":5,"v":8,"he":"וַיַּחְפֹּץ עַמִּי כִּי נִקְרָא אֶת־שֵׁם הַמָּקוֹם נֶפִי עַל־כֵּן קְרָאנֻהוּ נֶפִי׃","en":"And my people would that we should call the name of the place Nephi; wherefore, we did call it Nephi."},{"d":"2028-02-12","ref":"2 Nephi 5:12","b":"2 Nephi","c":5,"v":12,"he":"וָאָבֵא אֲנִי נֶפִי גַּם הַסְּפָרִים הַחֲקוּקִים עַל־לוּחוֹת הַנְּחֹשֶׁת וְגַם הַכַּדּוּר אוֹ הַמַּצְפֵּן אֲשֶׁר הוּכַן לְאָבִי בְּיַד־יְהוָה כַּכָּתוּב׃","en":"And I, Nephi, had also brought the records which were engraven upon the plates of brass; and also the ball, or compass, which was prepared for my father by the hand of the Lord, according to that which is written."},{"d":"2028-02-13","ref":"2 Nephi 5:15","b":"2 Nephi","c":5,"v":15,"he":"וָאֲלַמֵּד אֶת־עַמִּי לִבְנוֹת בִּנְיָנִים וְלַעֲבֹד בְּכׇל־מְלֶאכֶת עֵץ וּבַרְזֶל וּנְחוּשָׁה וּנְחֹשֶׁת וּפְלָדָה וְזָהָב וָכֶסֶף וּמַחְצָבִים יְקָרִים אֲשֶׁר הָיוּ לָרֹב מְאֹד׃","en":"And I did teach my people to build buildings, and to work in all manner of wood, and of iron, and of copper, and of brass, and of steel, and of gold, and of silver, and of precious ores, which were in great abundance."}]});
